import{_ as o,o as t,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"Провайдеры генерации видео","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/providers/video.md","filePath":"ru/integrations/providers/video.md","lastUpdated":1792323081000}'),a={name:"ru/integrations/providers/video.md"};function n(i,e,s,c,l,g){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="проваидеры-генерации-видео" tabindex="-1">Провайдеры генерации видео <a class="header-anchor" href="#проваидеры-генерации-видео" aria-label="Permalink to &quot;Провайдеры генерации видео&quot;">​</a></h1><p>Bot в Memoh могут генерировать видео через инструмент <code>generate_video</code>. Чтобы включить его, нужны две вещи:</p><ol><li><strong>Видеопровайдер</strong> хотя бы с одной видеомоделью, настроенный в <strong>Settings → Integrations → Video</strong>.</li><li>Модель <strong>Video Generation Model</strong>, назначенная Bot в <strong>Bot Settings → Multimedia</strong>.</li></ol><p>Если Bot не назначена видеомодель, инструмент <code>generate_video</code> ему не предлагается.</p><hr><h2 id="поддерживаемые-проваидеры" tabindex="-1">Поддерживаемые провайдеры <a class="header-anchor" href="#поддерживаемые-проваидеры" aria-label="Permalink to &quot;Поддерживаемые провайдеры&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Провайдер</th><th>Client Type</th><th>Base URL по умолчанию</th></tr></thead><tbody><tr><td><strong>OpenRouter</strong></td><td><code>openrouter-video</code></td><td><code>https://openrouter.ai/api</code></td></tr><tr><td><strong>ModelArk (BytePlus)</strong></td><td><code>modelark-video</code></td><td><code>https://ark.ap-southeast.bytepluses.com/api/v3</code></td></tr><tr><td><strong>Volcengine (Ark)</strong></td><td><code>volcengine-video</code></td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td></tr></tbody></table><p>Каждому провайдеру нужен <strong>API Key</strong>; <strong>Base URL</strong> необязателен — без него используется значение по умолчанию из таблицы выше.</p><p>Шаблоны из комплекта содержат актуальные пресеты моделей Seedance / Veo / Doubao-Seedance:</p><ul><li><strong>OpenRouter</strong>: <code>bytedance/seedance-2.0</code>, <code>google/veo-3.1-fast</code>, <code>google/veo-3.1-lite</code></li><li><strong>ModelArk</strong>: <code>dreamina-seedance-2-0-260128</code>, <code>dreamina-seedance-2-0-fast-260128</code>, <code>dreamina-seedance-2-5</code></li><li><strong>Volcengine</strong>: <code>doubao-seedance-2-0-260128</code>, <code>doubao-seedance-2-0-fast-260128</code>, <code>doubao-seedance-2-5</code></li></ul><p>OpenRouter также поддерживает <strong>Import Models</strong> из своего живого каталога. ModelArk и Volcengine не отдают список моделей по сети, поэтому их модели берутся из шаблона или добавляются вручную.</p><hr><h2 id="настроика" tabindex="-1">Настройка <a class="header-anchor" href="#настроика" aria-label="Permalink to &quot;Настройка&quot;">​</a></h2><ol><li>Откройте <strong>Settings → Integrations → Video</strong>.</li><li>Добавьте провайдер из списка шаблонов (OpenRouter, ModelArk или Volcengine).</li><li>Введите API-ключ, меняйте base URL только при использовании нестандартной конечной точки и сохраните.</li><li>Проверьте раздел <strong>Video Models</strong>: если список пуст, импортируйте модели от провайдера или добавьте модель вручную.</li><li>Откройте у Bot <strong>Settings → Multimedia</strong> и выберите <strong>Video Generation Model</strong>.</li></ol><hr><h2 id="как-bot-этим-пользуется" tabindex="-1">Как Bot этим пользуется <a class="header-anchor" href="#как-bot-этим-пользуется" aria-label="Permalink to &quot;Как Bot этим пользуется&quot;">​</a></h2><p>Просто попросите Bot сделать видео обычными словами. Под капотом:</p><ul><li><code>generate_video</code> запускает <strong>фоновую задачу</strong> и сразу возвращает ID задачи; генерация обычно занимает минуты, и Bot проверяет прогресс своими инструментами фоновых задач.</li><li>Инструмент принимает текстовый <code>prompt</code>, а также необязательные <code>duration_seconds</code>, <code>resolution</code> (например, <code>720p</code>/<code>1080p</code>), <code>aspect_ratio</code> (например, <code>16:9</code>, <code>9:16</code>, <code>1:1</code>), зависящий от провайдера <code>size</code> и <code>generate_audio</code>.</li><li>Готовое видео скачивается в рабочее пространство Bot по пути <code>/data/generated-videos/&lt;task_id&gt;.mp4</code> (<code>.webm</code>/<code>.mov</code> — в зависимости от вывода провайдера).</li><li>Видео <strong>никуда не отправляется автоматически</strong> — Bot доставляет его вложением к сообщению, а ещё его можно забрать с вкладки <strong>Files</strong> рабочего пространства.</li></ul><p>Если в момент завершения генерации рабочее пространство недоступно, задача всё равно завершается — с предупреждением и URL результата от провайдера, но на диск ничего не сохраняется.</p><hr><h2 id="связанные-страницы" tabindex="-1">Связанные страницы <a class="header-anchor" href="#связанные-страницы" aria-label="Permalink to &quot;Связанные страницы&quot;">​</a></h2><ul><li><a href="./llm.html">Провайдеры и модели</a></li><li><a href="./../../guides/container.html">Управление рабочим пространством Bot</a></li></ul>',22)])])}const u=o(a,[["render",n]]);export{h as __pageData,u as default};
